// Kody mascot mark (192×192 PNG, same asset as
// packages/worker/public/android-chrome-192x192.png) embedded for satori,
// which needs image sources inlined as data URIs.
const KODY_LOGO_PNG_BASE64 =
	''

export function getKodyLogoDataUri(): string {
	return `data:image/png;base64,${KODY_LOGO_PNG_BASE64}`
}
